1	//! Compiled-rule matching, lexicographic specificity, and load-time conflicts.
2	
3	use std::cmp::Ordering;
4	
5	use crate::{ACTION_CLASSES, normalize};
6	
7	#[derive(Debug, Clone, PartialEq, Eq)]
8	pub(crate) enum HostPattern {
9	    Bare(String),
10	    Exact(String),
11	    AnySubdomain(String),
12	}
13	
14	#[derive(Debug, Clone)]
15	pub(crate) struct CompiledRule {
16	    pub(crate) method: Option<String>,
17	    pub(crate) host: HostPattern,
18	    pub(crate) path: Option<String>,
19	    folded_path: Option<String>,
20	    pub(crate) action_class: &'static str,
21	    specificity: Specificity,
22	}
23	
24	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
25	struct Specificity {
26	    host_kind: u8,
27	    host_labels: usize,
28	    path_kind: u8,
29	    literal_count: usize,
30	    inverted_wildcard_count: usize,
31	    literal_prefix: usize,
32	    method: u8,
33	}
34	
35	impl Ord for Specificity {
36	    fn cmp(&self, other: &Self) -> Ordering {
37	        (
38	            self.host_kind,
39	            self.host_labels,
40	            self.path_kind,
41	            self.literal_count,
42	            self.inverted_wildcard_count,
43	            self.literal_prefix,
44	            self.method,
45	        )
46	            .cmp(&(
47	                other.host_kind,
48	                other.host_labels,
49	                other.path_kind,
50	                other.literal_count,
51	                other.inverted_wildcard_count,
52	                other.literal_prefix,
53	                other.method,
54	            ))
55	    }
56	}
57	
58	impl PartialOrd for Specificity {
59	    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
60	        Some(self.cmp(other))
61	    }
62	}
63	
64	#[derive(Debug)]
65	pub(crate) enum CompileError {
66	    Host,
67	    Method,
68	    Path,
69	    ActionClass(String),
70	}
71	
72	#[derive(Debug)]
73	pub(crate) enum ConflictCheckError {
74	    TooComplex { first: usize, second: usize },
75	}
76	
77	impl CompiledRule {
78	    pub(crate) fn new(
79	        method: Option<&str>,
80	        base_host: &str,
81	        subdomain: Option<&str>,
82	        path: Option<&str>,
83	        action_class: String,
84	    ) -> Result<Self, CompileError> {
85	        let base_host = normalize::host(base_host).ok_or(CompileError::Host)?;
86	        let host = match subdomain {
87	            None => HostPattern::Bare(base_host),
88	            Some("*") => HostPattern::AnySubdomain(base_host),
89	            Some(value) => {
90	                let host = format!("{value}.{base_host}");
91	                HostPattern::Exact(normalize::host(&host).ok_or(CompileError::Host)?)
92	            }
93	        };
94	        let method = match method {
95	            Some(value) => Some(normalize::method(value).ok_or(CompileError::Method)?),
96	            None => None,
97	        };
98	        let path = match path {
99	            Some(value) => {
100	                let normalized = normalize::pattern_path(value).ok_or(CompileError::Path)?;
101	                (normalized.len() <= normalize::MAX_PATTERN_BYTES)
102	                    .then_some(normalized)
103	                    .ok_or(CompileError::Path)
104	                    .map(Some)?
105	            }
106	            None => None,
107	        };
108	        let folded_path = path
109	            .as_deref()
110	            .map(normalize::lowercase_path_outside_escapes);
111	        let action_class = ACTION_CLASSES
112	            .iter()
113	            .copied()
114	            .find(|known| *known == action_class)
115	            .ok_or(CompileError::ActionClass(action_class))?;
116	        let specificity = specificity(&host, method.is_some(), path.as_deref());
117	        Ok(Self {
118	            method,
119	            host,
120	            path,
121	            folded_path,
122	            action_class,
123	            specificity,
124	        })
125	    }
126	
127	    pub(crate) fn matches(
128	        &self,
129	        method: &str,
130	        host: &str,
131	        path: &str,
132	        case_folded_path: bool,
133	    ) -> bool {
134	        self.method
135	            .as_deref()
136	            .is_none_or(|expected| expected == method)
137	            && host_matches(&self.host, host)
138	            && self
139	                .folded_path
140	                .as_deref()
141	                .filter(|_| case_folded_path)
142	                .or(self.path.as_deref())
143	                .is_none_or(|pattern| glob_matches(pattern, path))
144	    }
145	
146	    pub(crate) fn compare_specificity(&self, other: &Self) -> Ordering {
147	        self.specificity.cmp(&other.specificity)
148	    }
149	}
150	
151	pub(crate) fn find_conflict(
152	    rules: &[CompiledRule],
153	) -> Result<Option<(usize, usize)>, ConflictCheckError> {
154	    let mut remaining_glob_overlap_states = MAX_TOTAL_GLOB_OVERLAP_STATES;
155	    for (right_index, right) in rules.iter().enumerate() {
156	        for (left_index, left) in rules[..right_index].iter().enumerate() {
157	            if left.action_class != right.action_class
158	                && left.specificity == right.specificity
159	                && methods_overlap(left.method.as_deref(), right.method.as_deref())
160	                && hosts_overlap(&left.host, &right.host)
161	            {
162	                match paths_overlap(
163	                    left.path.as_deref(),
164	                    right.path.as_deref(),
165	                    &mut remaining_glob_overlap_states,
166	                ) {
167	                    Ok(true) => return Ok(Some((left_index, right_index))),
168	                    Ok(false) => {}
169	                    Err(()) => {
170	                        return Err(ConflictCheckError::TooComplex {
171	                            first: left_index,
172	                            second: right_index,
173	                        });
174	                    }
175	                }
176	            }
177	        }
178	    }
179	    Ok(None)
180	}
181	
182	fn specificity(host: &HostPattern, has_method: bool, path: Option<&str>) -> Specificity {
183	    let host_kind = u8::from(!matches!(host, HostPattern::AnySubdomain(_)));
184	    let host_labels = match host {
185	        HostPattern::Bare(value) | HostPattern::Exact(value) | HostPattern::AnySubdomain(value) => {
186	            value.split('.').count()
187	        }
188	    };
