305	/// Product traversal of two `*` glob NFAs. The sentinel represents any byte
306	/// not currently present as a literal and keeps the alphabet finite.
307	const MAX_TOTAL_GLOB_OVERLAP_STATES: usize = 4_000_000;
308	
309	fn globs_overlap(left: &str, right: &str, remaining_states: &mut usize) -> Result<bool, ()> {
310	    let (left, right) = (left.as_bytes(), right.as_bytes());
311	    let width = right.len().checked_add(1).ok_or(())?;
312	    let states = left
313	        .len()
314	        .checked_add(1)
315	        .and_then(|height| height.checked_mul(width))
316	        .ok_or(())?;
317	    if states > *remaining_states {
318	        return Err(());
319	    }
320	    *remaining_states -= states;
321	    let mut seen = vec![false; states];
322	    let mut queue = std::collections::VecDeque::from([(0usize, 0usize)]);
323	    while let Some((i, j)) = queue.pop_front() {
324	        let state = i * width + j;
325	        if seen[state] {
326	            continue;
327	        }
328	        seen[state] = true;
329	        if i == left.len() && j == right.len() {
330	            return Ok(true);
331	        }
332	        if left.get(i) == Some(&b'*') {
333	            queue.push_back((i + 1, j));
334	        }
335	        if right.get(j) == Some(&b'*') {
336	            queue.push_back((i, j + 1));
337	        }
338	        let mut alphabet = vec![0];
339	        if let Some(&byte) = left.get(i).filter(|&&byte| byte != b'*') {
340	            alphabet.push(byte);
341	        }
342	        if let Some(&byte) = right.get(j).filter(|&&byte| byte != b'*') {
343	            alphabet.push(byte);
344	        }
345	        for byte in alphabet {
346	            let next_left = transition(left, i, byte);
347	            let next_right = transition(right, j, byte);
348	            if let (Some(next_left), Some(next_right)) = (next_left, next_right) {
349	                queue.push_back((next_left, next_right));
350	            }
351	        }
352	    }
353	    Ok(false)
354	}
