356	fn transition(pattern: &[u8], index: usize, byte: u8) -> Option<usize> {
357	    match pattern.get(index) {
358	        Some(b'*') => Some(index),
359	        Some(&literal) if literal == byte => Some(index + 1),
360	        _ => None,
361	    }
362	}
