243	fn paths_overlap(
244	    left: Option<&str>,
245	    right: Option<&str>,
246	    remaining_states: &mut usize,
247	) -> Result<bool, ()> {
248	    // Equal patterns always overlap. More importantly, this check must happen
249	    // before spending the bounded wildcard-analysis budget: an identical pair
250	    // is an unambiguous conflict, not an analysis failure.
251	    if left == right {
252	        return Ok(true);
253	    }
254	    match (left, right) {
255	        (None, _) | (_, None) => Ok(true),
256	        (Some(left), Some(right)) if !left.contains('*') && !right.contains('*') => Ok(false),
257	        (Some(left), Some(right)) if !left.contains('*') => Ok(glob_matches(right, left)),
258	        (Some(left), Some(right)) if !right.contains('*') => Ok(glob_matches(left, right)),
259	        (Some(left), Some(right)) if literal_ends_diverge(left, right) => Ok(false),
260	        (Some(left), Some(right)) => globs_overlap(left, right, remaining_states),
261	    }
262	}
