        assert_exact_work(["/*ab", "/*ac"], 8, None);
        // Literal ends that agree establish the conflict at the same price.
        assert_exact_work(["/v*a*bc", "/v*ab*c"], 9, Some((0, 1)));
        // Exact paths read both patterns in full.
