    assert!(!message.contains("[truncated]"), "{message}");

    let over_limit = "n".repeat(257);
    let message = load(&[&set(&over_limit, "acme.com", &rules)])
        .await
        .err()
        .unwrap()
        .to_string();
    assert!(!message.contains(&over_limit), "{message}");
    assert!(message.contains("[truncated]"), "{message}");
}

